"""
File that contains all the reference ground loads and ground heat exchanger (GHE) parameters from 
the reference article of Ahmadfard and Bernier (2019).

Reference
Ahmadfard, M., & Bernier, M. (2019). A review of vertical ground heat exchanger sizing tools 
including an inter-model comparison. Renewable and Sustainable Energy Reviews, 110, 247–265. 
https://doi.org/10.1016/j.rser.2019.04.045
"""

function case_1()
    """
        case_1()
    """

    # Ground hourly heat load
    Q = loads_case_1()  

    # Borehole configuration parameters
    n = (x = 1, y = 1)      # Number of boreholes in x/y axes
    nb = 1                  # Total number of boreholes
    B = 6.0                 # Borehole spacing (m)
    D = 4.0                 # Buried depth (m)
    r = (b = 0.075,         # Borehole radius (m)
        o = 0.0167,         # Outer pipe radius (m)
        i = 0.0137)         # Inner pipe radius (m)
    s = 0.075               # Shank spacing (m)

    # Material properties
    ρ = (f = 1052.0,)       # Fluid density (kg/m³)
    C = (f = ρ.f * 3795.0,  # Fluid volumetric specific heat (J/m³K)
        s = 2073600.0,      # Ground volumetric specific heat
        g = 3.9e6,          # Grout volumetric specific heat
        p = 1.54e6)         # Pipe volumetric specific heat
    μ = (f = 5.2e-3,)       # Fluid viscosity (Pa·s)

    # Thermal properties
    k = (s = 1.8,           # Ground thermal conductivity (W/mK)
        g = 1.4,            # Grout thermal conductivity
        p = 0.43,           # Pipe thermal conductivity
        f = 0.48)           # Fluid thermal conductivity

    # Temperature parameters
    T = (g = 17.5,          # Initial ground temperature (°C)
        L = 0.0,            # Minimum inlet temperature
        H = 35.)            # Maximum inlet temperature

    # System configuration
    R = (b = 0.13,)         # Borehole thermal resistance (m·K/W)
    V = 0.1*maximum(abs.(Q))/(1000.0*ρ.f) # Total fluid flow rate (m³/s)
    
    return (; Q, n, nb, B, D, r, s, ρ, C, μ, k, T, R, V)
end

function case_2()
    """
        case_2()
    """
    # Ground hourly heat load
    Q = loads_case_2()  

    # Borehole configuration parameters
    n = (x = 12, y = 10)    # Number of boreholes in x/y axes
    nb = 120                # Total number of boreholes
    B = 6.0                 # Borehole spacing (m)
    D = 3.0                 # Buried depth (m)
    r = (b = 0.054,         # Borehole radius (m)
        o = 0.0167,         # Outer pipe radius (m)
        i = 0.0137)         # Inner pipe radius (m)
    s = 0.0471              # Shank spacing (m)

    # Material properties
    ρ = (f = 1026.0,)       # Fluid density (kg/m³)
    C = (f = ρ.f * 4019.0,  # Volumetric fluid specific heat (J/m³K)
        s = 2.877e6,        # Ground specific heat
        g = 3.9e6,          # Grout specific heat
        p = 1.54e6)         # Pipe specific heat
    μ = (f = 3.37e-3,)      # Fluid viscosity (Pa·s)

    # Thermal properties
    k = (s = 2.25,          # Ground conductivity (W/mK)
        g = 1.73,           # Grout conductivity
        p = 0.45,           # Pipe conductivity
        f = 0.468)          # Fluid conductivity

    # Temperature parameters
    T = (g = 12.41,         # Initial ground temp (°C)
        L = 4.4,            # Min inlet temp
        H = 35.0)           # Max inlet temp

    # System configuration
    R = (b = 0.113,)        # Borehole thermal resistance (m·K/W)
    V = 29 / ρ.f * nb       # Total fluid flow rate (m³/s)

    return (; Q, n, nb, B, D, r, s, ρ, C, μ, k, T, R, V)
end

function case_3()
    """
        case_3()
    """
    # Ground hourly heat load
    Q = loads_case_3()  

    # Borehole configuration parameters
    n = (x = 7, y = 7)      # Number of boreholes in x/y axes
    nb = 49                 # Total number of boreholes
    B = 5.0                 # Borehole spacing (m)
    D = 2.5                 # Buried depth (m)
    r = (b = 0.075,         # Borehole radius (m)
        o = 0.0167,         # Outer pipe radius (m)
        i = 0.013)          # Inner pipe radius (m)
    s = 0.075               # Shank spacing (m)

    # Material properties
    ρ = (f = 1026.0,)       # Fluid density (kg/m³)
    C = (f = ρ.f * 4019.0,  # Volumetric fluid specific heat (J/m³K)
        s = 2.592e6,        # Ground specific heat
        g = 3.9e6,          # Grout specific heat
        p = 1.54e6)         # Pipe specific heat
    μ = (f = 3.37e-3,)      # Fluid viscosity (Pa·s)

    # Thermal properties
    k = (s = 2.25,          # Ground conductivity (W/mK)
        g = 1.73,           # Grout conductivity
        p = 0.4,            # Pipe conductivity
        f = 0.468)          # Fluid conductivity

    # Temperature parameters
    T = (g = 10.0,           # Initial ground temp (°C)
        L = 0.0,             # Min inlet temp
        H = 35.0)            # Max inlet temp

    # System configuration
    R = (b = 0.1,)           # Borehole thermal resistance (m·K/W)
    V = 33.1 / ρ.f * nb      # Total fluid flow rate (m³/s)

    return (; Q, n, nb, B, D, r, s, ρ, C, μ, k, T, R, V)
end

function case_4()
    """
        case_4()
    """
    # Ground hourly heat load
    Q = loads_case_4()  

    # Borehole configuration parameters
    n = (x = 5, y = 5)      # Number of boreholes in x/y axes
    nb = 25                 # Total number of boreholes
    B = 8.0                 # Borehole spacing (m)
    D = 4.0                 # Buried depth (m)
    r = (b = 0.075,         # Borehole radius (m)
        o = 0.0167,         # Outer pipe radius (m)
        i = 0.013)          # Inner pipe radius (m)
    s = 0.083               # Shank spacing (m)

    # Material properties
    ρ = (f = 1026.0,)       # Fluid density (kg/m³)
    C = (f = ρ.f * 4019,    # Volumetric fluid specific heat (J/m³K)
        s = 2.052e6,        # Ground specific heat
        g = 3.9e6,          # Grout specific heat
        p = 1.54e6)         # Pipe specific heat
    μ = (f = 3.37e-3,)      # Fluid viscosity (Pa·s)

    # Thermal properties
    k = (s = 1.9,           # Ground conductivity (W/mK)
        g = 0.69,           # Grout conductivity
        p = 0.4,            # Pipe conductivity
        f = 0.468)          # Fluid conductivity

    # Temperature parameters
    T = (g = 15.0,          # Initial ground temp (°C)
        L = 0.0,            # Min inlet temp
        H = 38.0)           # Max inlet temp

    # System configuration
    R = (b = 0.2,)          # Borehole thermal resistance (m·K/W)
    V = 0.074*maximum(abs.(Q))/(1000*ρ.f) # Total fluid flow rate (m³/s)
    
    return (; Q, n, nb, B, D, r, s, ρ, C, μ, k, T, R, V)
end

